      hu: ["Dunkelsteinerwald", "Védelmi struktúrák", "Történelmi ösvények", "Túracélpont"],
      ro: ["Dunkelsteinerwald", "Structuri defensive", "Poteci istorice", "Destinație pentru drumeții"],
      en: ["Dunkelsteinerwald", "Defensive structures", "Historical paths", "Hiking destination"],
